const $=id=>document.getElementById(id);let key='',sendId=null;
const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.get('key')){key=fragment.get('key');history.replaceState(null,'',location.pathname)}else try{key=sessionStorage.getItem('gg-push-sender')||''}catch{}
async function api(path,body){const r=await fetch('/api/push/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+key,...(body?{'content-type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})}),v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v}
function status(t){$('status').textContent=t}
async function refresh(){try{const s=await api('status');$('subscribers').textContent=s.subscribers;$('lastSend').textContent=s.lastSend?`Last send: ${new Date(s.lastSend.at).toLocaleString()} · ${s.lastSend.accepted} accepted, ${s.lastSend.failed} failed, ${s.lastSend.expired} expired.`:'No broadcasts sent yet.';$('unlock').hidden=true;$('desk').hidden=false;try{sessionStorage.setItem('gg-push-sender',key)}catch{}status('Connected. Ready to send.')}catch(e){status(e.message);$('unlock').hidden=false;$('desk').hidden=true}}
$('unlock').onsubmit=e=>{e.preventDefault();key=$('senderKey').value.trim();$('senderKey').value='';refresh()};$('refresh').onclick=refresh;
for(let n=1;n<=9;n++){$('race').add(new Option('Race '+n,n))}
function preview(){sendId=null;$('previewTitle').textContent=$('title').value;$('previewBody').textContent=$('body').value||'Your message appears here.';$('remaining').textContent=(180-$('body').value.length)+' characters left'}
$('title').oninput=preview;$('body').oninput=preview;$('race').onchange=()=>{sendId=null};
$('template').onclick=async()=>{try{const response=await fetch('/api/late-mail',{cache:'no-store'});if(!response.ok)throw Error('Saved late mail unavailable');const s=await response.json();let n=Number($('race').value);if(!n){const report=s.meeting.races.filter(r=>r.status==='pending'&&Date.parse(r.startAt)>Date.now()).sort((a,b)=>Date.parse(a.startAt)-Date.parse(b.startAt))[0];if(!report)throw Error('No upcoming race found. Choose a race or write an update.');n=report.number;$('race').value=String(n)}const pick=s.selections[String(n)],r=s.meeting.races.find(x=>x.number===n);$('title').value=`Race ${n} · Geoff’s saved view`;$('body').value=[r.condition||'Going unconfirmed',pick?.revisedTip?.display||pick?.baselineTip?.display||'No firm selection',`Saved ${new Date(s.updated).toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit',timeZone:'Australia/Melbourne'})} AEDT. Open for details.`].join(' · ').slice(0,180);preview();status('Loaded the saved edition. Review the message before sending.')}catch(e){status(e.message)}};
$('sendForm').onsubmit=async e=>{e.preventDefault();$('send').disabled=true;status('Sending…');sendId||=crypto.randomUUID();try{const r=await api('send',{id:sendId,title:$('title').value,body:$('body').value,race:Number($('race').value)});await refresh();status(`${r.accepted}/${r.total} accepted by push services. ${r.failed} failed, ${r.expired} expired, ${r.rateLimited} rate limited. Device display is not confirmed.${r.duplicate?' Already sent; no repeat broadcast.':''}`)}catch(e){status(e.message+' You can retry; the same message ID prevents a repeat completed broadcast.')}finally{$('send').disabled=false}};
$('lock').onclick=()=>{key='';try{sessionStorage.removeItem('gg-push-sender')}catch{}$('desk').hidden=true;$('unlock').hidden=false;status('Locked.')};if(key)refresh();
